function option(x:string,locale:NativeLocale):string{
 let m=x.match(/^Article\s+(\d+(?:\([0-9]+\))?)$/);if(m)return (locale==="hi"?"अनुच्छेद ":"ਅਨੁਛੇਦ ")+m[1];
 m=x.match(/^(\d+)(?:st|nd|rd|th) Constitutional Amendment$/);if(m)return m[1]+(locale==="hi"?"वाँ संविधान संशोधन":"ਵੀਂ ਸੰਵਿਧਾਨ ਸੋਧ");
 m=x.match(/^(\d+) years$/);if(m)return m[1]+(locale==="hi"?" वर्ष":" ਸਾਲ");
 m=x.match(/^(\d+) days$/);if(m)return m[1]+(locale==="hi"?" दिन":" ਦਿਨ");
 const sch:Record<string,Pair>={"Seventh Schedule":p("सातवीं अनुसूची","ਸੱਤਵੀਂ ਅਨੁਸੂਚੀ"),"Ninth Schedule":p("नौवीं अनुसूची","ਨੌਵੀਂ ਅਨੁਸੂਚੀ"),"Tenth Schedule":p("दसवीं अनुसूची","ਦਸਵੀਂ ਅਨੁਸੂਚੀ"),"Eleventh Schedule":p("ग्यारहवीं अनुसूची","ਗਿਆਰਵੀਂ ਅਨੁਸੂਚੀ")};
 if(sch[x])return sch[x]![locale];
 const z=O[x];if(z)return z[locale];
 throw new Error("POL-CP-021 missing localized option: "+x);
}
function localize(q:(typeof ENGLISH)[number],i:number,locale:PolLocaleV1):PolLocalizedQuestionV1{
 const base={...q,chapterId:"POL-001" as const,cpId:"POL-CP-021",qlName:q.qlId,reviewOnly:true as const,runtimeRegistered:false as const};
 if(locale==="en")return {...base,options:[...q.options],canonicalAnswer:q.options[q.correctIndex]!,locale,localizationV1:{version:POL_LOCALIZATION_V1,englishQuestionId:q.questionId,semanticInvariant:true,cpInvariant:true,qlInvariant:true,difficultyInvariant:true,sourceInvariant:true,optionOrderInvariant:true,correctIndexInvariant:true,reviewOnly:true}};
 let stem=STEMS[i]![locale],explanation=EXPS[i]![locale],options=q.options.map(x=>option(x,locale));
 if(locale==="pa"){stem=applyPolityPunjabiNativePassV1(stem);explanation=applyPolityPunjabiNativePassV1(explanation);options=options.map(applyPolityPunjabiNativePassV1);}
 return {...base,questionId:q.questionId+"-"+locale.toUpperCase(),stem,options,canonicalAnswer:options[q.correctIndex]!,explanation,locale,localizationV1:{version:POL_LOCALIZATION_V1,englishQuestionId:q.questionId,semanticInvariant:true,cpInvariant:true,qlInvariant:true,difficultyInvariant:true,sourceInvariant:true,optionOrderInvariant:true,correctIndexInvariant:true,reviewOnly:true}};
}
export function generatePolCp021LocalizedReviewV1(locale:PolLocaleV1):PolLocalizedQuestionV1[]{return ENGLISH.map((q,i)=>localize(q,i,locale));}
export const POL_CP021_LOCALIZATION_V1_ENGLISH_COUNT=ENGLISH.length;
